mapper.update:
UPDATE vault_credentials
SET archived_at = COALESCE(archived_at, NOW()),
    ciphertext = NULL, nonce = NULL, wrapped_dek = NULL,
    format_version = NULL, key_provider = NULL, key_version = NULL,
    updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND vault_external_id = #{vaultExternalID}
AND external_id = #{credentialExternalID}
AND deleted_at IS NULL
RETURNING

mapper.delete:
