mapper.select:
SELECT 
FROM vault_credentials
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND vault_external_id = #{params.VaultExternalID}
AND deleted_at IS NULL
AND archived_at IS NULL

    AND (created_at, uuid) < (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})

ORDER BY created_at DESC, uuid DESC
LIMIT #{params.Limit}
